/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadDMSans = makeLoadFont('DMSans');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: dmSansFamily } = loadDMSans();



export type SeedanceFolderProps = Record<string, any>;

const SeedanceFolder: React.FC<SeedanceFolderProps> = ({
  backgroundColor = "#F2EFE9",
  transparentBackground = false,
  durationInSeconds = 8,
  papers = [
    { titleText: "Vox style" },
    { titleText: "Dynamic Motion" },
    { titleText: "Stop Motion" }
  ],
  folderLabel = "Seedance 2.0",
  primaryGlowColor = "#FFD8A8",
  accentColor = "#4A3B32",
  paperColor = "#FAF9F6",
  folderColor = "#E6DCC3",
  shakeIntensity = 1.5,
  particleCount = 18,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Basic styling configurations
  const finalBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Frame-based deterministic Jitter / Stop-motion effect (changes every 3 frames)
  const jitterFrame = Math.floor(frame / 3);
  const getJitter = (id: string, intensity: number = 1) => {
    const x = (random(`${id}-x-${jitterFrame}`) - 0.5) * intensity;
    const y = (random(`${id}-y-${jitterFrame}`) - 0.5) * intensity;
    const rot = (random(`${id}-r-${jitterFrame}`) - 0.5) * (intensity * 0.5);
    return { x, y, rot };
  };

  // Dimensions
  const folderW = width * 0.78;
  const folderH = height * 0.28;
  const paperW = folderW * 0.82;
  const paperH = folderH * 1.15;

  // Animation Timing / Springs (Entrance and Exit sequences)
  const totalFrames = durationInSeconds * fps;
  const folderCloseFrame = totalFrames - 40;

  const folderEntrance = spring({
    frame,
    fps,
    config: { stiffness: 110, damping: 13, mass: 1 },
  });

  const folderClose = spring({
    frame: frame - folderCloseFrame,
    fps,
    config: { stiffness: 80, damping: 14 },
  });

  // Dynamic particle shine reveal timing
  const shineReveal = spring({
    frame: frame - 18,
    fps,
    config: { stiffness: 80, damping: 14 },
  });

  // Folder paths (Back Flap and Front Pocket)
  const getBackFlapPath = (w: number, h: number) => {
    const tabH = h * 0.16;
    const tabW = w * 0.38;
    const transitionW = w * 0.08;
    return `
      M 6 ${tabH} 
      L 6 12 
      Q 10 6 18 6 
      L ${tabW} 6 
      Q ${tabW + 12} 6 ${tabW + 18} ${tabH - 4}
      L ${tabW + transitionW} ${tabH}
      L ${w - 18} ${tabH}
      Q ${w - 6} ${tabH} ${w - 6} ${tabH + 12}
      L ${w - 6} ${h - 12}
      Q ${w - 6} ${h} ${w - 18} ${h}
      L 18 ${h}
      Q 6 ${h} 6 ${h - 12}
      Z
    `;
  };

  const getFrontFlapPath = (w: number, h: number) => {
    const tabH = h * 0.16;
    return `
      M 6 ${tabH + 15}
      Q 6 ${tabH} 22 ${tabH}
      L ${w - 22} ${tabH}
      Q ${w - 6} ${tabH} ${w - 6} ${tabH + 15}
      L ${w - 6} ${h - 15}
      Q ${w - 6} ${h} ${w - 15} ${h}
      L 15 ${h}
      Q 6 ${h} 6 ${h - 15}
      Z
    `;
  };

  // Background Rays (Radial golden pencil lines)
  const rays: React.ReactNode[] = [];
  const rayCount = 22;
  const innerRadius = width * 0.18;
  const outerRadiusMax = width * 0.42;

  for (let i = 0; i < rayCount; i++) {
    const angle = (i * 2 * Math.PI) / rayCount;
    const degree = (angle * 180) / Math.PI;

    // Filter rays to only display around top and sides (skipping bottom area)
    if (degree > 15 && degree < 165) continue;

    const seed = `ray-${i}`;
    const lengthFactor = 0.65 + random(`${seed}-len`) * 0.35;
    const outerRadius = innerRadius + (outerRadiusMax - innerRadius) * lengthFactor;

    const x1 = width / 2 + Math.cos(angle) * innerRadius;
    const y1 = height * 0.54 + Math.sin(angle) * innerRadius;

    const x2 = width / 2 + Math.cos(angle) * outerRadius;
    const y2 = height * 0.54 + Math.sin(angle) * outerRadius;

    // Introduce waviness to the ray stroke
    const midX = (x1 + x2) / 2 + (random(`${seed}-midx`) - 0.5) * 12;
    const midY = (y1 + y2) / 2 + (random(`${seed}-midy`) - 0.5) * 12;

    const rayLength = Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
    const dashOffset = rayLength * (1 - shineReveal);

    const isAccentColor = random(`${seed}-color`) > 0.65;
    const rColor = isAccentColor ? accentColor : primaryGlowColor;
    const strokeW = isAccentColor ? 1.5 : 2.5;

    rays.push(
      <path
        key={seed}
        d={`M ${x1} ${y1} Q ${midX} ${midY} ${x2} ${y2}`}
        fill="none"
        stroke={rColor}
        strokeWidth={strokeW}
        strokeLinecap="round"
        strokeDasharray={`${rayLength} ${rayLength}`}
        strokeDashoffset={dashOffset}
        opacity={0.8 * (1 - folderClose)}
        style={{ transition: "none" }}
      />
    );
  }

  // Floating particles / Shimmer stars
  const particles: React.ReactNode[] = [];
  for (let i = 0; i < particleCount; i++) {
    const seed = `particle-${i}`;
    const startX = width * (0.1 + random(`${seed}-x`) * 0.8);
    const startY = height * (0.2 + random(`${seed}-y`) * 0.55);
    const size = 5 + random(`${seed}-size`) * 10;
    const isDiamond = random(`${seed}-shape`) > 0.45;
    const pColor = random(`${seed}-pColor`) > 0.35 ? primaryGlowColor : accentColor;

    // Delicate procedural float & drift
    const floatOffset = Math.sin(frame * 0.04 + random(`${seed}-phase`) * Math.PI) * 10;
    const driftOffset = frame * 0.22 * (random(`${seed}-speed`) + 0.4);

    const appearFrame = 20 + random(`${seed}-delay`) * 20;
    const scale = spring({
      frame: frame - appearFrame,
      fps,
      config: { stiffness: 90, damping: 11 },
    });

    if (scale <= 0) continue;

    const rotVal = frame * (random(`${seed}-rot`) - 0.5) * 0.4;
    const pJitter = getJitter(seed, shakeIntensity * 0.5);

    const style: React.CSSProperties = {
      position: "absolute",
      left: 0,
      top: 0,
      width: size,
      height: size,
      backgroundColor: isDiamond ? "transparent" : pColor,
      border: isDiamond ? `2px solid ${pColor}` : "none",
      borderRadius: isDiamond ? "2px" : "50%",
      transform: `translate(${startX + pJitter.x}px, ${startY - driftOffset + floatOffset + pJitter.y}px) scale(${scale}) rotate(${rotVal + (isDiamond ? 45 : 0)}deg)`,
      opacity: 0.85 * (1 - folderClose),
      pointerEvents: "none",
      transition: "none",
    };

    particles.push(<div key={seed} style={style} />);
  }

  // Underneath shadowed pencil swirls (gives hand-drawn grounding)
  const shadowW = width * 0.62;
  const shadowH = height * 0.045;
  const shadowLines: React.ReactNode[] = [];
  for (let i = 0; i < 5; i++) {
    const seed = `shadow-line-${i}`;
    const wOffset = (random(`${seed}-w`) - 0.5) * 22;
    const hOffset = (random(`${seed}-h`) - 0.5) * 5;
    const yOffset = (random(`${seed}-y`) - 0.5) * 6;
    const rot = (random(`${seed}-rot`) - 0.5) * 2.5;

    shadowLines.push(
      <ellipse
        key={seed}
        cx={width / 2}
        cy={height * 0.81 + yOffset}
        rx={(shadowW / 2 + wOffset) * folderEntrance}
        ry={(shadowH / 2 + hOffset) * folderEntrance}
        fill="none"
        stroke={accentColor}
        strokeWidth={1.8}
        opacity={(0.32 - i * 0.05) * folderEntrance * (1 - folderClose)}
        transform={`rotate(${rot}, ${width / 2}, ${height * 0.81})`}
        style={{ transition: "none" }}
      />
    );
  }

  // Wavy text scribbles configurations
  const scribbleStartY = paperH * 0.32;
  const scribbleSpacing = 24;
  const scribbleLineCount = 5;
  const scribbleW = paperW * 0.74;

  // Outer sketchy pencil swirls wrapping around folder sides
  const swirlReveal = spring({
    frame: frame - 5,
    fps,
    config: { stiffness: 80, damping: 14 },
  });

  const leftSwirlPath = `M ${width * 0.28} ${height * 0.72} C ${width * 0.05} ${height * 0.72}, ${width * 0.02} ${height * 0.56}, ${width * 0.18} ${height * 0.52} C ${width * 0.3} ${height * 0.49}, ${width * 0.22} ${height * 0.42}, ${width * 0.1} ${height * 0.45}`;
  const rightSwirlPath = `M ${width * 0.72} ${height * 0.74} C ${width * 0.95} ${height * 0.74}, ${width * 0.98} ${height * 0.58}, ${width * 0.82} ${height * 0.54} C ${width * 0.7} ${height * 0.51}, ${width * 0.78} ${height * 0.44}, ${width * 0.9} ${height * 0.47}`;

  const leftJitter = getJitter("leftSwirl", shakeIntensity * 0.8);
  const rightJitter = getJitter("rightSwirl", shakeIntensity * 0.8);

  // Folder overall position jitter
  const folderJitter = getJitter("folder-overall", shakeIntensity);

  // Procedural pencil shading pattern inside the Front Flap (kraft paper sketch)
  const shadingLines: React.ReactNode[] = [];
  const spacing = 10;
  for (let y = 0; y < folderH; y += spacing) {
    const waviness = 1.2;
    const startX = 0;
    const stepW = folderW / 6;
    let d = `M ${startX} ${y}`;
    for (let i = 1; i <= 6; i++) {
      const curX = i * stepW;
      const midX = curX - stepW / 2;
      const noiseY = (random(`shade-${y}-${i}`) - 0.5) * waviness;
      d += ` Q ${midX} ${y + noiseY} ${curX} ${y}`;
    }

    shadingLines.push(
      <path
        key={`shade-${y}`}
        d={d}
        fill="none"
        stroke={accentColor}
        strokeWidth={1.2}
        opacity={0.15}
        style={{ transition: "none" }}
      />
    );
  }

  // Folder Closing Offsets
  const folderYOffset = interpolate(folderClose, [0, 1], [0, height * 0.65], {
    extrapolateRight: "clamp",
  });
  const folderScaleClose = interpolate(folderClose, [0, 1], [1, 0.8], {
    extrapolateRight: "clamp",
  });
  const closeRotationX = interpolate(folderClose, [0, 1], [0, -20], {
    extrapolateRight: "clamp",
  });

  // Calculate paper dropping stagger timeline
  const paperCount = papers.length;
  const dropStartDelay = 12;
  const dropEndFrame = totalFrames - 45;
  const availableFrames = dropEndFrame - dropStartDelay;
  const interval = paperCount > 1 ? availableFrames / paperCount : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor, overflow: "hidden", perspective: 1000 }}>
      {/* Background Vignette and Radial Glow */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          background: `radial-gradient(circle at 50% 55%, ${backgroundColor} 25%, #E6DFD5 100%)`,
          zIndex: 1,
          transition: "none",
        }}
      />

      {/* Central Golden Burst Aura */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "54%",
          width: width * 0.7,
          height: width * 0.7,
          transform: `translate(-50%, -50%) scale(${interpolate(shineReveal, [0, 1], [0.5, 1.25])})`,
          opacity: interpolate(shineReveal, [0, 1], [0, 0.42]) * (1 - folderClose),
          background: `radial-gradient(circle, ${primaryGlowColor} 0%, rgba(255,255,255,0) 70%)`,
          pointerEvents: "none",
          zIndex: 2,
          transition: "none",
        }}
      />

      {/* Canvas Elements Wrapper */}
      <div style={{ position: "relative", width: "100%", height: "100%", zIndex: 3 }}>
        {/* Shadow base ellipse */}
        {shadowLines}

        {/* Background radial rays */}
        <svg
          style={{
            position: "absolute",
            width,
            height,
            pointerEvents: "none",
            zIndex: 4,
            overflow: "visible",
            transition: "none",
          }}
        >
          {rays}
        </svg>

        {/* Sketch Swirls (Left & Right) */}
        <svg
          style={{
            position: "absolute",
            width,
            height,
            pointerEvents: "none",
            zIndex: 5,
            overflow: "visible",
            transition: "none",
          }}
        >
          {/* Left Swirl */}
          <path
            d={leftSwirlPath}
            fill="none"
            stroke={accentColor}
            strokeWidth={1.8}
            opacity={0.4 * (1 - folderClose)}
            strokeDasharray="400"
            strokeDashoffset={400 * (1 - swirlReveal)}
            transform={`translate(${leftJitter.x}, ${leftJitter.y}) rotate(${leftJitter.rot}, ${width * 0.15}, ${height * 0.58})`}
            style={{ transition: "none" }}
          />
          {/* Right Swirl */}
          <path
            d={rightSwirlPath}
            fill="none"
            stroke={accentColor}
            strokeWidth={1.8}
            opacity={0.4 * (1 - folderClose)}
            strokeDasharray="400"
            strokeDashoffset={400 * (1 - swirlReveal)}
            transform={`translate(${rightJitter.x}, ${rightJitter.y}) rotate(${rightJitter.rot}, ${width * 0.85}, ${height * 0.6})`}
            style={{ transition: "none" }}
          />
        </svg>

        {/* Floating golden/pencil particles */}
        <div style={{ position: "absolute", width, height, pointerEvents: "none", zIndex: 6 }}>
          {particles}
        </div>

        {/* Main Folder Assembly */}
        <div
          style={{
            position: "absolute",
            left: (width - folderW) / 2,
            top: height * 0.51,
            width: folderW,
            height: folderH,
            transform: `translate(${folderJitter.x}px, ${folderJitter.y + folderYOffset}px) scale(${folderEntrance * folderScaleClose}) rotate(${folderJitter.rot}deg) rotateX(${closeRotationX}deg)`,
            transformOrigin: "bottom center",
            zIndex: 10,
            transition: "none",
          }}
        >
          {/* Unique IDs for clip paths to prevent collision */}
          <svg style={{ position: "absolute", width: 0, height: 0 }}>
            <defs>
              <clipPath id="folderBackClip">
                <path d={getBackFlapPath(folderW, folderH)} />
              </clipPath>
              <clipPath id="folderFrontClip">
                <path d={getFrontFlapPath(folderW, folderH)} />
              </clipPath>
              <clipPath id="paperClip">
                <rect width={paperW} height={paperH} rx={12} ry={12} />
              </clipPath>
            </defs>
          </svg>

          {/* LAYER 1: Folder Back Flap */}
          <svg
            width={folderW}
            height={folderH}
            style={{ position: "absolute", overflow: "visible", zIndex: 1, transition: "none" }}
          >
            {/* Filled background of back flap */}
            <path d={getBackFlapPath(folderW, folderH)} fill={folderColor} opacity={0.9} />
            {/* Sketch border lines (Double struck for organic sketch texture) */}
            <path
              d={getBackFlapPath(folderW + 1, folderH - 1)}
              fill="none"
              stroke={accentColor}
              strokeWidth={3}
              strokeLinecap="round"
            />
            <path
              d={getBackFlapPath(folderW - 1, folderH + 1)}
              fill="none"
              stroke={accentColor}
              strokeWidth={1.5}
              opacity={0.65}
              strokeLinecap="round"
            />
          </svg>

          {/* LAYER 2: Paper Sheets (Drop from the top of the canvas into the folder one at a time) */}
          {papers.map((paper, i) => {
            const dropStart = dropStartDelay + i * interval;
            const dropSpring = spring({
              frame: frame - dropStart,
              fps,
              config: { stiffness: 95, damping: 14, mass: 1.1 },
            });

            const dropProgress = dropSpring;
            const startY = -height * 0.8;
            const endY = -folderH * 0.38 + (i * 12);
            const paperY = interpolate(dropProgress, [0, 1], [startY, endY]);

            const restRotation = ((i * 4) % 7) - 3.5;
            const paperRotation = interpolate(dropProgress, [0, 0.7, 1], [-12, 4, restRotation]);
            const paperX = ((i * 14) % 24) - 12;

            // Generate procedural scribbles for each paper
            const paperScribbles: React.ReactNode[] = [];
            for (let j = 0; j < scribbleLineCount; j++) {
              const lineY = scribbleStartY + j * scribbleSpacing;
              const lineSeed = `scribble-${i}-${j}`;

              let d = `M ${paperW * 0.13} ${lineY}`;
              const steps = 14;
              const stepW = scribbleW / steps;
              for (let s = 1; s <= steps; s++) {
                const curX = paperW * 0.13 + s * stepW;
                const midX = curX - stepW / 2;
                const waveHeight = s % 2 === 0 ? 1.8 : -1.8;
                const noiseY = (random(`${lineSeed}-${s}`) - 0.5) * 1.5;
                d += ` Q ${midX} ${lineY + waveHeight + noiseY} ${curX} ${lineY}`;
              }

              const scribbleProgress = spring({
                frame: frame - (dropStart + 10 + j * 3),
                fps,
                config: { stiffness: 100, damping: 15 },
              });

              const pathLength = scribbleW;
              const scribbleDashOffset = pathLength * (1 - scribbleProgress);

              paperScribbles.push(
                <path
                  key={lineSeed}
                  d={d}
                  fill="none"
                  stroke="#6B5B52"
                  strokeWidth={2}
                  opacity={0.65}
                  strokeLinecap="round"
                  strokeDasharray={`${pathLength} ${pathLength}`}
                  strokeDashoffset={scribbleDashOffset}
                  style={{ transition: "none" }}
                />
              );
            }

            return (
              <div
                key={`paper-${i}`}
                style={{
                  position: "absolute",
                  left: (folderW - paperW) / 2 + paperX,
                  top: paperY,
                  width: paperW,
                  height: paperH,
                  zIndex: 2 + i,
                  transform: `rotate(${paperRotation}deg)`,
                  transformOrigin: "center bottom",
                  transition: "none",
                }}
              >
                {/* Paper Shape with Clip for Textured inner content */}
                <div
                  style={{
                    position: "absolute",
                    width: "100%",
                    height: "100%",
                    backgroundColor: paperColor,
                    borderRadius: "12px",
                    boxShadow: "0 6px 15px rgba(0,0,0,0.06)",
                    border: `3px solid ${accentColor}`,
                    overflow: "hidden",
                    transition: "none",
                  }}
                >
                  {/* Soft paper crinkle texture */}
                  <div
                    style={{
                      position: "absolute",
                      width: "100%",
                      height: "100%",
                      background: `linear-gradient(135deg, rgba(255,255,255,0.7) 0%, rgba(220,215,200,0.2) 100%)`,
                      transition: "none",
                    }}
                  />

                  {/* Decorative Subtle Paper Creases */}
                  <svg
                    width={paperW}
                    height={paperH}
                    style={{ position: "absolute", opacity: 0.16, pointerEvents: "none" }}
                  >
                    <path
                      d={`M ${paperW * 0.1} ${paperH * 0.12} L ${paperW * 0.9} ${paperH * 0.18}`}
                      stroke={accentColor}
                      strokeWidth={1.5}
                    />
                    <path
                      d={`M ${paperW * 0.2} ${paperH * 0.85} L ${paperW * 0.8} ${paperH * 0.89}`}
                      stroke={accentColor}
                      strokeWidth={1.5}
                    />
                  </svg>

                  {/* Paper sheet title content */}
                  <div
                    style={{
                      marginTop: paperH * 0.1,
                      textAlign: "center",
                      fontFamily: playfairFamily,
                      fontSize: Math.min(width, height) * 0.055,
                      fontWeight: "500",
                      color: "#332A24",
                      opacity: interpolate(dropProgress, [0.6, 1], [0, 1]),
                      transform: `translateY(${interpolate(dropProgress, [0, 1], [15, 0])}px)`,
                      transition: "none",
                    }}
                  >
                    {paper.titleText}
                  </div>

                  {/* Hand-drawn written scribbles on paper */}
                  <svg
                    width={paperW}
                    height={paperH}
                    style={{
                      position: "absolute",
                      top: 0,
                      left: 0,
                      pointerEvents: "none",
                      transition: "none",
                    }}
                  >
                    {paperScribbles}
                  </svg>
                </div>
              </div>
            );
          })}

          {/* LAYER 3: Folder Front Flap (Covering paper bottom) */}
          <div
            style={{
              position: "absolute",
              width: folderW,
              height: folderH,
              zIndex: 10,
              transition: "none",
            }}
          >
            {/* Front flap shape rendering with sketch shading lines clipped */}
            <svg
              width={folderW}
              height={folderH}
              style={{ position: "absolute", overflow: "visible", transition: "none" }}
            >
              <g clipPath="url(#folderFrontClip)">
                {/* Folder base background color */}
                <path d={getFrontFlapPath(folderW, folderH)} fill={folderColor} />
                {/* Kraft pencil shading lines overlay */}
                {shadingLines}
              </g>

              {/* Dual-drawn sketchy outlines for front folder */}
              <path
                d={getFrontFlapPath(folderW + 1, folderH - 1)}
                fill="none"
                stroke={accentColor}
                strokeWidth={4.5}
                strokeLinecap="round"
              />
              <path
                d={getFrontFlapPath(folderW - 1, folderH + 1)}
                fill="none"
                stroke={accentColor}
                strokeWidth={2}
                opacity={0.7}
                strokeLinecap="round"
              />
            </svg>

            {/* Folder Front Flap Text Content: "Seedance 2.0" */}
            <div
              style={{
                position: "absolute",
                top: "55%",
                left: "50%",
                transform: "translate(-50%, -50%)",
                width: "90%",
                textAlign: "center",
                fontFamily: dmSansFamily,
                fontSize: Math.min(width, height) * 0.08,
                fontWeight: "bold",
                fontStyle: "italic",
                color: accentColor,
                opacity: interpolate(folderEntrance, [0.3, 1], [0, 1]),
                zIndex: 11,
                userSelect: "none",
                textShadow: "0.5px 0.5px 0px rgba(255,255,255,0.4)",
                transition: "none",
              }}
            >
              {folderLabel}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SeedanceFolder;